/bin/bash -lc "bedtools coverage -a windows100k.bed -b aln.filtered.bam -counts > cov100k_counts.tsv; python3 - <<'PY'
rows=[]
for line in open('cov100k_counts.tsv'):
    c,s,e,n=line.strip().split('\\t'); s=int(s); e=int(e); n=int(n)
    rows.append((s,e,n))
def mean(a,b):
    vals=[n for s,e,n in rows if s>=a and e<=b]
    return sum(vals)/len(vals), len(vals)
for a,b in [(36000001,36400000),(35000001,35600000),(36400001,36700000),(30000000,36000000),(36400000,45000000)]:
 print(a,b,mean(a,b))
PY"

