/bin/bash -lc "samtools view -b -F 256 -q 10 -f 0x2 -f 0x40 -o aln.r1.bam aln.sorted.bam && samtools index aln.r1.bam && bedtools coverage -a windows100k.bed -b aln.r1.bam -mean > cov100k_r1.tsv; python3 - <<'PY'
rows=[]
for line in open('cov100k_r1.tsv'):
 c,s,e,v=line.strip().split('\\t'); s=int(s); e=int(e); v=float(v)
 rows.append((s,e,v))
def mean(a,b):
 vals=[v for s,e,v in rows if s>=a and e<=b]
 return sum(vals)/len(vals),len(vals)
for a,b in [(36000001,36400000),(35000001,35600000),(36400001,36700000)]:
 print(a,b,mean(a,b))
print('ratio',mean(36000001,36400000)[0]/((mean(35000001,35600000)[0]*6+mean(36400001,36700000)[0]*3)/9))
PY"

